BEGIN;

-- Reverts 20260905340000_repair_misdirected_artist_references.sql.
--
-- HOW THIS WAS BUILT, stated plainly: the change was applied before these files
-- were generated, so the pre-change documents were not captured live. They are
-- reconstructed by inverting the three edits, which were mechanical and fully
-- specified -- one artistId plus its displayText in Zeo Munoz, and one
-- displayText in each of Miriam Cruz's two documents. Nothing else in either
-- document was touched, so the inversion is exact rather than approximate.
--
-- Restoring this puts a link reading "Wason Brazoban" back on Victor Victor's
-- profile. Only run it if the forward migration was itself wrong.

UPDATE editorial_entity_references r
   SET target_artist_id = (SELECT id FROM artists WHERE slug = 'victor-victor')
  FROM editorial_documents d
  JOIN artists a ON a.id = d.owner_artist_id
 WHERE r.editorial_document_id = d.id
   AND a.slug = 'zeo-munoz'
   AND d.locale = 'en'
   AND r.target_artist_id = (SELECT id FROM artists WHERE slug = 'wason-brazoban');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Zeo Muñoz (born in Santiago, Dominican Republic) is a Dominican singer-songwriter recognized for his introspective lyrics, acoustic sound, and emotionally driven storytelling. Raised in the municipality of Navarrete, Muñoz has become one of the most distinctive voices in the modern Dominican cantautor movement. His work blends folk, pop, and Dominican melodic traditions, earning him recognition across the Dominican Republic, the diaspora, and the New York music scene. He has been nominated for the Premios Soberano and has collaborated with several major Dominican artists.","type":"text"}]},{"type":"paragraph","content":[{"text":"Early Life and Background","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Zeo Muñoz was born in Santiago and taken to Navarrete at three days old, where he was raised by his grandparents. Although Navarrete is officially part of the province of Santiago, Muñoz identifies strongly with the town and often refers to himself as “from Navarrete.”","type":"text"}]},{"type":"paragraph","content":[{"text":"His early interest was not singing but writing. Music entered his life through local cultural groups, including a rock band formed by friends and an Andean music ensemble led by cultural promoter Cuki Guzmán. His first instrument was a Peruvian flute, followed later by the guitar.","type":"text"}]},{"type":"paragraph","content":[{"text":"Muñoz purchased his first guitar by saving small remittances sent by his mother, who had emigrated to the United States through the Panama–Mexico route in the early 1990s. He saved “peso by peso” until he reached the equivalent of 100 dollars, which he used to buy the instrument that would eventually define his artistic path.","type":"text"}]},{"type":"paragraph","content":[{"text":"Migration to the United States","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"At age 17, Muñoz moved to New York City. He enrolled in university and studied International Criminology with a focus on Government, while working various jobs including lifeguard, swimming instructor, and real estate agent.","type":"text"}]},{"type":"paragraph","content":[{"text":"During this period, music remained a private hobby. He played guitar at home, wrote songs, and spent time in local parks playing chess and tennis. His early years in New York were marked by loneliness and uncertainty, experiences that later shaped his songwriting.","type":"text"}]},{"type":"paragraph","content":[{"text":"Musical Beginnings","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Muñoz’s first public musical experience occurred in a university rock band, where he initially served as a songwriter and guitarist. When the lead singer left the group, Muñoz temporarily took over vocals to maintain rehearsals. This was the first time he discovered the emotional connection of singing his own lyrics.","type":"text"}]},{"type":"paragraph","content":[{"text":"His professional transition began after experiencing symptoms of depression. A psychologist advised him to pursue one of his hobbies more consistently. Muñoz chose music.","type":"text"}]},{"type":"paragraph","content":[{"text":"He approached a small bar on 184th Street in Manhattan and asked to sing “a couple of songs.” The owner invited him to perform on a Tuesday night. His early audiences were small, but the performances gradually grew, leading him to abandon real estate and dedicate himself fully to music.","type":"text"}]},{"type":"paragraph","content":[{"text":"Rise in the New York Scene","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Zeo Muñoz became a regular performer in bohemian venues across Manhattan and Queens, building a loyal following among Dominican and Latin American audiences. He recorded homemade demos, burned CDs, and distributed them to listeners. His song “Millones de Gallos Rojos” became a turning point, spreading organically through voice notes and social media.","type":"text"}]},{"type":"paragraph","content":[{"text":"He credits the Dominican community in New York for encouraging him to pursue music professionally.","type":"text"}]},{"type":"paragraph","content":[{"text":"Collaboration with ","type":"text","marks":[{"type":"bold"}]},{"type":"artistReference","attrs":{"artistId":"4b4bf9da-fe4a-4fc6-be40-1b1b5413dfb3","displayText":"Wason Brazobán  ","occurrenceId":"7e9aad65-939a-46de-9c07-002459e5ec4f"}}]},{"type":"paragraph","content":[{"text":"A major milestone in Muñoz’s career occurred when Wason Brazobán, one of the Dominican Republic’s most prominent singer-songwriters, attended one of his performances. Brazobán joined him on stage and later contacted Muñoz to praise “Millones de Gallos Rojos,” predicting it would be a hit.","type":"text"}]},{"type":"paragraph","content":[{"text":"Brazobán recorded vocals for the song in Muñoz’s living room before heading to the airport. He advised Muñoz to release the solo version first so that his own fame would not overshadow the emerging artist. Muñoz frequently refers to Brazobán as his “musical godfather.”","type":"text"}]},{"type":"paragraph","content":[{"text":"Solo Career and Albums","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Muñoz released his debut album “No se lo digan a ella”, which he produced largely at home using digital recording tools. His second album, “Amuleto”, showcased greater rhythmic diversity, including bachata, bolero, and acoustic ballads. Both albums received positive reception for their emotional depth and production quality.","type":"text"}]},{"type":"paragraph","content":[{"text":"His songwriting style is characterized by poetic imagery, vulnerability, and themes of heartbreak, nostalgia, and personal growth.","type":"text"}]},{"type":"paragraph","content":[{"text":"Notable Works and Collaborations","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Zeo Muñoz has collaborated with several major Dominican artists, including:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"4b4bf9da-fe4a-4fc6-be40-1b1b5413dfb3","displayText":"Wason Brazobán  ","occurrenceId":"727c5af5-04c0-4cd3-8ab3-f52420d3d7b9"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas  ","occurrenceId":"3f1d4226-01c5-446f-a3d3-abdcc377cfe3"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"4b4bf9da-fe4a-4fc6-be40-1b1b5413dfb3","displayText":"Víctor Víctor  ","occurrenceId":"72d8e2ee-e1a3-4bd5-b3f0-fe44cac59ea8"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona  ","occurrenceId":"f5cae579-118d-49e0-a7fb-2190476813fd"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Franklin Brito  ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Ronnie Cruz","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"His song “Difícil Entender” was inspired by a dream in which he wrote a song for ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"69a9fc92-57cf-4f4c-b666-e78f9672d6cf"}},{"text":". The track later became one of his most acclaimed compositions.","type":"text"}]},{"type":"paragraph","content":[{"text":"Musical Style","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Zeo Muñoz’s music blends:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Acoustic guitar  ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Folk and cantautor traditions  ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Dominican melodic sensibilities  ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Poetic and introspective lyrics  ","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Minimalist arrangements with emotional focus  ","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"His voice and writing have been described as intimate, honest, and deeply personal.","type":"text"}]},{"type":"paragraph","content":[{"text":"Recognition","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Muñoz has been nominated for the Premios Soberano, the Dominican Republic’s highest artistic honor. He has also gained significant support from the Dominican diaspora, particularly in New York, Queens, and the Cibao region.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy and Impact","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Although still early in his career, Zeo Muñoz has become one of the most promising Dominican singer-songwriters of his generation. His organic rise from small bars to national recognition, combined with his authenticity and emotional storytelling, has positioned him as a leading figure in the modern Dominican cantautor movement.","type":"text"}]}]}'::jsonb, revision = 3, updated_at = now()
 WHERE id = (select d.id from editorial_documents d join artists a on a.id=d.owner_artist_id where a.slug='zeo-munoz' and d.locale='en');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Miriam Cruz — Miriam Aracelis Cruz Ramírez, born in Santo Domingo on 17 August 1968 — is a Dominican merengue singer, bandleader and actress. She was the lead voice of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6778e4a3-8f63-420f-bdd4-9a0a7e5cacc5","displayText":"Las Chicas del Can","occurrenceId":"27ccae7e-05f0-4603-8425-89ae2eb9ef36"}},{"text":", and since 1992 she has led her own orchestra.","type":"text"}]},{"type":"paragraph","content":[{"text":"The first all-women merengue orchestra","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Las Chicas del Can began as Las Muchachas, a group ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0d7c68df-63ca-4b6b-9a8f-c6c1a62912f1","displayText":"Belkis Concepción","occurrenceId":"5c581f41-95d1-41aa-9afb-889f22e320bd"}},{"text":" put together in 1976. The broadcaster ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"b3c1135d-755c-41d6-9d99-476ff9c56a78"}},{"text":" gave them the name they became known by, and from the end of 1981 ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"908b63f3-ced7-4486-afff-e5df950c8893"}},{"text":" took the group on and ran it through his company.","type":"text"}]},{"type":"paragraph","content":[{"text":"It was the first fully female merengue orchestra in the country — not a singer with a band behind her, but women playing the horns, the keyboards and the percussion as well as singing.","type":"text"}]},{"type":"paragraph","content":[{"text":"In 1984 Belkis Concepción had to step away, and Cruz, until then the second vocalist and still a teenager, took the front. By the end of that year Vargas had made the change permanent.","type":"text"}]},{"type":"paragraph","content":[{"text":"The eighties","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"What followed was one of the biggest runs any Dominican group has had. Besos Callejeros, La Media María, Sukaína, Juana la Cubana, Ta’ Pillao and El Negro No Puede came out of that decade, and gold and platinum records came with them.","type":"text"}]},{"type":"paragraph","content":[{"text":"The touring went further than merengue usually travelled: Venezuela, Guatemala, Costa Rica, Colombia and Peru, then Spain, the Netherlands, France, Italy and Finland, and then Japan.","type":"text"}]},{"type":"paragraph","content":[{"text":"El Negro No Puede has an afterlife she had nothing to do with. Its hook came from Zangalewa, a Cameroonian marching song, and it reappeared in 2010 as the chorus of Shakira’s Waka Waka — a line that travelled from Cameroon to Santo Domingo to the World Cup.","type":"text"}]},{"type":"paragraph","content":[{"text":"Her own orchestra","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1992 most of the group left with her to start something of their own, and she formed Miriam Cruz y Las Chicas. She has led it ever since.","type":"text"}]},{"type":"paragraph","content":[{"text":"Nada Común had arrived in 1991; Nueva Vida followed in 1993, then Punto y Aparte in 2001, Aquí Estoy in 2006, Siempre Diva in 2013, Me Sacudí in 2015 and Salí de Ti in 2017. La Loba, Tómalo Tú, Agua de Sal, Es Cosa de Él, La Carnada and Esa Loca are among the songs that carried.","type":"text"}]},{"type":"paragraph","content":[{"text":"Standing alone in the category","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The Soberano for best merengue orchestra went to her repeatedly through the 2010s. In 2013 she took it for a second consecutive year, beating Juan Luis Guerra in another category the same night. Esa Loca won merengue of the year in 2014.","type":"text"}]},{"type":"paragraph","content":[{"text":"By 2016 she had four of them, and that year she was the only woman nominated in the category at all — up against ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ae3c0afb-0e0a-4506-bbe6-a59c3c68bb1e","displayText":"Eddy Herrera","occurrenceId":"4c57c2e6-dac4-4afb-b2a7-18f41a8f73ad"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dee014d6-cb3c-4abb-9262-165538277a0d","displayText":"Héctor Acosta","occurrenceId":"20d0b08f-c9aa-4809-aa89-a2a9ff6e2473"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3422883e-7048-48af-bb03-c68c8c557ee4","displayText":"Los Hermanos Rosario","occurrenceId":"3d224898-13d5-4229-abd5-751e67007beb"}},{"text":". That is the whole argument for why she matters, stated as a list of names.","type":"text"}]},{"type":"paragraph","content":[{"text":"In 2022, four decades into the work, she released Tú Ganas and played Lincoln Center in New York. She has also worked as an actress.","type":"text"}]}]}'::jsonb, revision = 2, updated_at = now()
 WHERE id = (select d.id from editorial_documents d join artists a on a.id=d.owner_artist_id where a.slug='miriam-cruz' and d.locale='en');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Miriam Cruz —Miriam Aracelis Cruz Ramírez, nacida en Santo Domingo el 17 de agosto de 1968— es una cantante, directora de orquesta y actriz de merengue dominicana. Fue la voz principal de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6778e4a3-8f63-420f-bdd4-9a0a7e5cacc5","displayText":"Las Chicas del Can","occurrenceId":"f34bee00-8e82-471d-aac7-d0eda83e39bc"}},{"text":", y desde 1992 dirige su propia orquesta.","type":"text"}]},{"type":"paragraph","content":[{"text":"La primera orquesta de merengue de mujeres","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Las Chicas del Can empezaron como Las Muchachas, un grupo que armó ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0d7c68df-63ca-4b6b-9a8f-c6c1a62912f1","displayText":"Belkis Concepción","occurrenceId":"bcce79d6-8a79-475d-a4aa-4afd1c1eae10"}},{"text":" en 1976. El presentador ","type":"text"},{"type":"artistReference","attrs":{"artistId":"faff18bd-3dbc-477a-bc38-859d611887f0","displayText":"Yaqui Núñez del Risco","occurrenceId":"e4bc1642-f338-4360-9548-c54c1530bf8a"}},{"text":" les puso el nombre con el que se hicieron conocidas, y desde finales de 1981 ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"01e54f26-6ada-449e-ae02-ecbf6c79774d"}},{"text":" tomó el grupo y lo manejó a través de su empresa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Fue la primera orquesta de merengue totalmente femenina del país: no una cantante con una banda detrás, sino mujeres tocando los metales, los teclados y la percusión además de cantar.","type":"text"}]},{"type":"paragraph","content":[{"text":"En 1984 Belkis Concepción tuvo que apartarse, y Cruz, hasta entonces la segunda vocalista y todavía una adolescente, pasó al frente. Para finales de ese año Vargas había hecho el cambio permanente.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los ochenta","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Lo que vino después fue uno de los tramos más grandes que ha tenido grupo dominicano alguno. Besos Callejeros, La Media María, Sukaína, Juana la Cubana, Ta’ Pillao y El Negro No Puede salieron de esa década, y con ellos los discos de oro y de platino.","type":"text"}]},{"type":"paragraph","content":[{"text":"Las giras llegaron más lejos de lo que solía llegar el merengue: Venezuela, Guatemala, Costa Rica, Colombia y Perú, después España, Países Bajos, Francia, Italia y Finlandia, y después Japón.","type":"text"}]},{"type":"paragraph","content":[{"text":"El Negro No Puede tiene una segunda vida en la que ella no tuvo nada que ver. Su estribillo venía de Zangalewa, una marcha camerunesa, y reapareció en 2010 como el coro del Waka Waka de Shakira: una frase que viajó de Camerún a Santo Domingo y de ahí al Mundial.","type":"text"}]},{"type":"paragraph","content":[{"text":"Su propia orquesta","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 1992 la mayoría del grupo se fue con ella a montar algo propio, y formó Miriam Cruz y Las Chicas. La dirige desde entonces.","type":"text"}]},{"type":"paragraph","content":[{"text":"Nada Común había salido en 1991; Nueva Vida vino en 1993, después Punto y Aparte en 2001, Aquí Estoy en 2006, Siempre Diva en 2013, Me Sacudí en 2015 y Salí de Ti en 2017. La Loba, Tómalo Tú, Agua de Sal, Es Cosa de Él, La Carnada y Esa Loca están entre las canciones que pegaron.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sola en la categoría","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El Soberano a la mejor orquesta de merengue le fue cayendo una y otra vez a lo largo de los años diez. En 2013 lo ganó por segundo año seguido, y esa misma noche se impuso a Juan Luis Guerra en otra categoría. Esa Loca ganó merengue del año en 2014.","type":"text"}]},{"type":"paragraph","content":[{"text":"Para 2016 ya tenía cuatro, y ese año era la única mujer nominada en la categoría: contra ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ae3c0afb-0e0a-4506-bbe6-a59c3c68bb1e","displayText":"Eddy Herrera","occurrenceId":"ce58ffa0-c49f-4bbb-a8c6-360ec1c837e3"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dee014d6-cb3c-4abb-9262-165538277a0d","displayText":"Héctor Acosta","occurrenceId":"decc7317-3fd9-4533-8c05-11c797fc3666"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3422883e-7048-48af-bb03-c68c8c557ee4","displayText":"Los Hermanos Rosario","occurrenceId":"22ad8d6c-7136-4479-a400-6fe66e355eb3"}},{"text":". Ése es el argumento entero de por qué ella importa, dicho como una lista de nombres.","type":"text"}]},{"type":"paragraph","content":[{"text":"En 2022, con cuatro décadas de trabajo encima, sacó Tú Ganas y se presentó en el Lincoln Center de Nueva York. Ha trabajado además como actriz.","type":"text"}]}]}'::jsonb, revision = 1, updated_at = now()
 WHERE id = (select d.id from editorial_documents d join artists a on a.id=d.owner_artist_id where a.slug='miriam-cruz' and d.locale='es');

UPDATE artists
   SET bio_en = replace(bio_en, 'Héctor Acosta “El Torito”', 'Héctor Acosta'),
       bio_es = replace(bio_es, 'Héctor Acosta “El Torito”', 'Héctor Acosta'),
       updated_at = now()
 WHERE slug = 'miriam-cruz';

COMMIT;
